  % Labels outside the figure
  \node[above left, lbl] at (A) {$A$};
  \node[above right, lbl] at (D) {$D$};
  \node[below left, lbl] at (B) {$B$};
  \node[below right, lbl] at (C) {$C$};
  \node[above right, lbl] at (E) {$E$};
\end{tikzpicture}
